const body = $input.first().json.body || {};
const course = body.course || 'Genel';
const content = body.content || '';
const count = body.count || 5;

const prompt = `Aşağıdaki ders notundan öğrencilerin SM-2 aralıklı tekrar yöntemiyle ezberlemesi için ${count} adet soru-cevap bilgi kartı (flashcard) üret.\n\nNot: ${content}\n\nÇıktıyı YALNIZCA şu JSON şemasında ver:\n{\n  "cards": [\n    {\n      "topic": "Konu Başlığı",\n      "question": "Soru veya Kavram",\n      "answer": "Net ve anlaşılır açıklama"\n    }\n  ]\n}`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://ollama:11434/api/generate',
  body: {
    model: 'qwen2.5:3b',
    prompt: prompt,
    format: 'json',
    stream: false
  },
  json: true
});

let parsed = {};
try {
  parsed = JSON.parse(response.response);
} catch (e) {
  parsed = { cards: [] };
}

return {
  json: {
    success: true,
    course: course,
    cards: (parsed.cards || []).map((c, i) => ({
      id: `${Date.now()}_${i}`,
      course: course,
      topic: c.topic || 'Genel Kavram',
      question: c.question,
      answer: c.answer,
      repetitions: 0,
      interval: 1,
      ease_factor: 2.5
    }))
  }
};
